package com.coffeeshop.service;import com.coffeeshop.model.ReportModels;import com.coffeeshop.repository.ReportRepository;import org.junit.jupiter.api.Test;import java.time.LocalDate;import static org.junit.jupiter.api.Assertions.*;class ReportServiceTest{private final Stub repo=new Stub();private final ReportService service=new ReportService(repo);@Test void delegatesValidRange(){LocalDate d=LocalDate.now();service.report(d.minusDays(7),d);assertEquals(d.minusDays(7),repo.from);assertEquals(d,repo.to);}@Test void rejectsMissingOrReversedRange(){LocalDate d=LocalDate.now();assertThrows(IllegalArgumentException.class,()->service.report(null,d));assertThrows(IllegalArgumentException.class,()->service.report(d,d.minusDays(1)));}@Test void rejectsExcessiveRange(){assertThrows(IllegalArgumentException.class,()->service.report(LocalDate.now().minusYears(3),LocalDate.now()));}private static final class Stub implements ReportRepository{LocalDate from,to;public ReportModels.Report load(LocalDate f,LocalDate t){from=f;to=t;return new ReportModels.Report(new ReportModels.Summary(0,java.math.BigDecimal.ZERO,java.math.BigDecimal.ZERO,java.math.BigDecimal.ZERO,java.math.BigDecimal.ZERO,java.math.BigDecimal.ZERO),java.util.List.of(),java.util.List.of(),java.util.List.of());}}}
